static void report_tail(void){U32 h,n=0,i,at=0;W16 p[260];char b[512],line[96];path(p,reports[selected]);h=CreateFileW(p,0x80000000,3,0,3,0,0);if(h==0xffffffff){append("No report file: test may have failed to start.");return;}while(ReadFile(h,b,sizeof(b),&n,0)&&n){for(i=0;i<n;i++){if(b[i]=='\n'){line[at]=0;score_feed(line);append(line);at=0;}else if(b[i]!='\r'&&at<95)line[at++]=b[i];}}if(at){line[at]=0;score_feed(line);append(line);}CloseHandle(h);}
