static U32 proc(U32 h,U32 m,U32 w,U32 l){if(m==0x0f){dirty=1;ValidateRect(h,0);return 0;}if(m==0x100){if((w==9||w==0xc2)&&!running&&selected>=9&&selected<=12&&score_ready[selected-9]){if(mode==3){count=scroll=0;score_case=0;report_tail();mode=2;}else if(mode==2||mode==0)mode=3;dirty=1;return 0;}if(mode==3&&(w==37||w==39)){score_page(w==37?-1:1);return 0;}if(w==38){if(mode==0)selected=selected?selected-1:13;else if(scroll+14<count)scroll++;dirty=1;}else if(w==40){if(mode==0)selected=(selected+1)%14;else if(scroll)scroll--;dirty=1;}else if(w==13||w==32||w==0xc1||w==0x70||w==0x41)activate();else if((w==27||w==8)&&!running){mode=0;dirty=1;}return 0;}if(m==0x202&&mode==0){U32 y=(l>>16)&65535;if(y>=36&&y<218){selected=(y-36)/13;activate();}return 0;}if(m==0x202&&mode==3&&!running&&((l>>16)&65535)>=210){U32 x=l&65535;if(x<90)score_page(-1);else if(x>230)score_page(1);else{count=scroll=0;score_case=0;report_tail();mode=2;dirty=1;}return 0;}if(m==0x202&&mode==2&&!running&&((l>>16)&65535)>=210){activate();return 0;}if(m==2){PostQuitMessage(0);return 0;}return DefWindowProcW(h,m,w,l);}
